import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    a = [int(x) for x in input_data[1:n+1]]

    left = 0
    right = n - 1
    last_val = 0
    res = []

    while left <= right:
        left_val = a[left]
        right_val = a[right]

        if left_val < last_val and right_val < last_val:
            # Both are smaller, we can't extend. Break.
            break

        candidates = []
        if left_val > last_val:
            candidates.append(('L', left_val))
        if right_val > last_val:
            candidates.append(('R', right_val))

        if not candidates:
            break

        # If only one candidate, take it
        if len(candidates) == 1:
            res.append(candidates[0][0])
            last_val = candidates[0][1]
            if candidates[0][0] == 'L':
                left += 1
            else:
                right -= 1
        else:
            # Both candidates are valid and > last_val
            if left_val < right_val:
                res.append('L')
                last_val = left_val
                left += 1
            else:
                res.append('R')
                last_val = right_val
                right -= 1

    print(len(res))
    print(''.join(res))

if __name__ == "__main__":
    solve()
